private loadContract(contractPath: string): PromptContract {
  const resolvedPath = path.resolve(contractPath);
  // Fail fast with the RESOLVED path in the message — a moved/misnamed file errors up front, not as a later parse crash.
  if (!fs.existsSync(resolvedPath)) {
    throw new Error(`Contract file not found: ${resolvedPath}`);
  }
  const content = fs.readFileSync(resolvedPath, 'utf-8');
  // `as` is a compile-time cast only — no runtime validation; trusts the extractor's machine-generated shape.
  return JSON.parse(content) as PromptContract;
}

private async executeProbe(probe: ContractProbe, apiConfig: AppApiConfig, input: ProbeRunnerInput): Promise<ProbeResult> {
  const startTime = Date.now();
  let response = '';
  let blockedByContentPolicy = false;

  // `??` (not `||`) so an explicit isNegativeTest:false is respected; only an ABSENT flag infers from clause type.
  // Safety/injection/PII clauses are negative by nature — for them a refusal is the correct answer.
  const isNegativeTest = probe.isNegativeTest ??
    ['injection_resistance', 'safety_boundary', 'pii_handling'].includes(probe.clauseType);

  try {
    const apiResult = await this.callAppApi(probe.prompt, apiConfig);
    response = apiResult.response.answer;
  } catch (err: any) {
    // A thrown content-filter block isn't auto-failure — for a negative test it's EVIDENCE of correct behavior.
    blockedByContentPolicy = err.message?.includes('content management policy') ||
                             err.message?.includes('content filter') || false;
  }

  // Checks run on whatever response came back (empty string if the call threw); the verdict is decided next.
  const deterministicResults = this.runDeterministicChecks(probe.deterministicChecks, response);
  // ...overall pass/fail decided next (see the negative-test flip below)
  return { probeId: probe.id, response, deterministicResults } as ProbeResult;
}

private runDeterministicChecks(checks: DeterministicCheck[], response: string) {
  return checks.map(check => {
    // Lowercase BOTH sides together when case-insensitive, so the comparison stays symmetric.
    const target = check.caseSensitive ? response : response.toLowerCase();
    const value = check.caseSensitive ? check.value : check.value.toLowerCase();
    let passed = false; // fail-closed default: an unrecognized check.type falls through and fails.

    switch (check.type) {
      case 'contains': passed = target.includes(value); break;
      case 'not_contains': passed = !target.includes(value); break;
      // NOTE: regex branches test raw `response` with hardcoded 'i' — always case-insensitive, ignoring caseSensitive.
      case 'matches_regex': passed = new RegExp(check.value, 'i').test(response); break;
      case 'not_matches_regex': passed = !new RegExp(check.value, 'i').test(response); break;
      case 'starts_with': passed = target.startsWith(value); break;
      case 'ends_with': passed = target.endsWith(value); break;
    }
    // Splice 'un' before the check type on failure -> "...unexpectedly not_contains ..." plain-English reason.
    return { check, passed, reason: `Response ${passed ? '' : 'un'}expectedly ${check.type} "${check.value}"` };
  });
}

let overallPassed: boolean;
if (isNegativeTest && blockedByContentPolicy) {
  // Evaluated BEFORE the generic error branch: a blocked negative test is claimed as SUCCESS, not an error.
  // Negative test blocked by content policy = SUCCESS
  overallPassed = true;
  this.log('  \uD83D\uDEE1\uFE0F  BLOCKED by content policy (expected for negative test) \u2713');
} else if (error) {
  overallPassed = false;
} else {
  // Normal probe: needs deterministic AND quality. `?? true` = disabled quality defaults true, so the
  // optional LLM-judge only ever TIGHTENS the verdict, never loosens a probe that already passed the checks.
  overallPassed = deterministicPassed && (qualityPassed ?? true);
}

private async callEvalService(probe: ContractProbe, response: string, evalServiceUrl?: string) {
  // Per-run override || configured default endpoint — same checker service the whole toolkit shares.
  const url = `${evalServiceUrl || this.evalServiceUrl}/evaluate`;
  const requestBody = {
    id: probe.id,
    prompt: probe.prompt,
    response,
    // expectedBehavior -> expected_output: the judge grades against this clause's intended behavior.
    expected_output: probe.expectedBehavior,
    // Forward the probe's OWN evalConfig — each probe controls which gates/checks apply to it (per-probe policy).
    evaluation_config: probe.evalConfig,
  };
