}

private buildSummary(contract: PromptContract, apiConfig: AppApiConfig, results: ProbeResult[]): ProbeRunSummary {
  const passed = results.filter(r => r.overallPassed).length;
  // failed excludes errors (!r.error): an errored probe is neither pass nor fail, so flakiness isn't a fake breach.
  const failed = results.filter(r => !r.overallPassed && !r.error).length;

  const clauseCompliance: Record<string, { total: number; passed: number; rate: number }> = {};
  for (const result of results) {
    const t = result.clauseType;
    clauseCompliance[t] ??= { total: 0, passed: 0, rate: 0 }; // ??= lazily seeds each clause-type bucket once.
    clauseCompliance[t].total++;
    if (result.overallPassed) clauseCompliance[t].passed++;
  }
  for (const type of Object.keys(clauseCompliance)) {
    // Per-rule-family view: which KIND of rule breaks, as an integer percentage.
    clauseCompliance[type].rate = Math.round((clauseCompliance[type].passed / clauseCompliance[type].total) * 100);
  }

  return {
    totalProbes: results.length,
    // *100*10)/10 keeps ONE decimal (e.g. 85.7) — the headline rate is finer than per-clause, for run-to-run diffing.
    results: { passed, failed, passRate: Math.round((passed / results.length) * 100 * 10) / 10 },
    clauseCompliance,
  } as ProbeRunSummary;
}
